import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static final int[][] SMALL = {{1}, {1, 1}, {1, 2, 1}, {1, 3, 3, 1}, {1, 4, 6, 4, 1}};

    // C(degree, i) mod 10 from Lucas' theorem mod 5 and mod 2, combined by CRT.
    static int coefficient(int degree, int i) {
        int nn = degree, kk = i, mod5 = 1;
        while (nn != 0 || kk != 0) {
            int u = nn % 5, v = kk % 5;
            if (v > u) {
                mod5 = 0;
                break;
            }
            mod5 = mod5 * SMALL[u][v] % 5;
            nn /= 5;
            kk /= 5;
        }
        int mod2 = (i & degree) == i ? 1 : 0;
        return mod5 % 2 == mod2 ? mod5 : mod5 + 5;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = (int) nextLong();
        int degree = n - 2, first = 0, second = 0;
        for (int i = 0; i <= degree; i++) {
            int c = coefficient(degree, i);
            first = (first + c * a[i]) % 10;
            second = (second + c * a[i + 1]) % 10;
        }
        System.out.println(first + "" + second);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

var small = [5][5]int{{1}, {1, 1}, {1, 2, 1}, {1, 3, 3, 1}, {1, 4, 6, 4, 1}}

// coefficient returns C(degree, i) mod 10 from Lucas' theorem mod 5 and mod 2, combined by CRT.
func coefficient(degree, i int) int {
	nn, kk, mod5 := degree, i, 1
	for nn != 0 || kk != 0 {
		u, v := nn%5, kk%5
		if v > u {
			mod5 = 0
			break
		}
		mod5 = mod5 * small[u][v] % 5
		nn /= 5
		kk /= 5
	}
	mod2 := 0
	if i&degree == i {
		mod2 = 1
	}
	if mod5%2 == mod2 {
		return mod5
	}
	return mod5 + 5
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(nextInt())
	a := make([]int, n)
	for i := range a {
		a[i] = int(nextInt())
	}
	degree, first, second := n-2, 0, 0
	for i := 0; i <= degree; i++ {
		c := coefficient(degree, i)
		first = (first + c*a[i]) % 10
		second = (second + c*a[i+1]) % 10
	}
	fmt.Printf("%d%d\n", first, second)
}
